//! s6_systemctl plugin — projects the op-s6-systemctl D-Bus daemon state.
//!
//! Exposes the daemon's liveness, interface metadata, and a snapshot of all
//! s6 service units so the UI can render a service manager panel from the schema.
//!
//! Schema-driven: every field here maps 1:1 to a UI widget in the schema renderer.
//!
//! OSCAL subids:
//!   obs.service.s6_systemctl.status@v1   — daemon liveness + unit list
//!   mut.service.s6_systemctl.start@v1    — start a unit via D-Bus
//!   mut.service.s6_systemctl.stop@v1     — stop a unit via D-Bus
//!   mut.service.s6_systemctl.restart@v1  — restart a unit via D-Bus
//!   mut.service.s6_systemctl.enable@v1   — enable a unit via D-Bus
//!   mut.service.s6_systemctl.disable@v1  — disable a unit via D-Bus

use anyhow::Result;
use async_trait::async_trait;
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use op_state_store::{FieldSchema, FieldType, PluginSchema};
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};

// ── State structs ─────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct S6SystemctlState {
    /// Whether the op-s6-systemctl D-Bus daemon is reachable.
    pub daemon_running: bool,
    /// D-Bus bus name the daemon registers.
    pub bus_name: String,
    /// D-Bus object path.
    pub object_path: String,
    /// D-Bus interface name.
    pub interface: String,
    /// All s6 service units with their current status.
    pub units: Vec<S6UnitStatus>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct S6UnitStatus {
    /// Service name (bare, no suffix).
    pub id: String,
    /// "active" | "inactive" | "failed" | "unknown"
    pub active_state: String,
    /// "running" | "dead" | "unknown"
    pub sub_state: String,
    /// Whether the unit starts at boot.
    pub enabled: bool,
    /// Main PID if running.
    pub main_pid: Option<u32>,
    /// Seconds the process has been up.
    pub up_time: Option<String>,
}

// ── Plugin ────────────────────────────────────────────────────────────────────

pub struct S6SystemctlPlugin;

impl S6SystemctlPlugin {
    pub fn new() -> Self {
        Self
    }

    /// Probe the daemon and enumerate units. Falls back to direct s6 CLI when
    /// the daemon isn't on the bus yet.
    async fn collect_state(&self) -> S6SystemctlState {
        let daemon_running = self.probe_daemon().await;
        let units = self.enumerate_units(daemon_running).await;

        S6SystemctlState {
            daemon_running,
            bus_name: "org.opdbus.v1.S6.Systemctl".to_string(),
            object_path: "/org/opdbus/v1/s6/systemctl".to_string(),
            interface: "org.opdbus.v1.S6.Systemctl".to_string(),
            units,
        }
    }

    /// Check if the daemon is registered on the system bus.
    async fn probe_daemon(&self) -> bool {
        use zbus::Connection;
        let Ok(conn) = Connection::system().await else {
            return false;
        };
        conn.call_method(
            Some("org.freedesktop.DBus"),
            "/org/freedesktop/DBus",
            Some("org.freedesktop.DBus"),
            "GetNameOwner",
            &"org.opdbus.v1.S6.Systemctl",
        )
        .await
        .is_ok()
    }

    /// Enumerate all units. Uses direct s6 CLI — no dependency on the daemon.
    async fn enumerate_units(&self, daemon_running: bool) -> Vec<S6UnitStatus> {
        // Get running services
        let running: std::collections::HashSet<String> = tokio::process::Command::new("s6-rc")
            .args(["-a", "list"])
            .output()
            .await
            .map(|o| {
                String::from_utf8_lossy(&o.stdout)
                    .lines()
                    .map(|l| l.trim().to_string())
                    .filter(|l| !l.is_empty())
                    .collect()
            })
            .unwrap_or_default();

        // Get all available services from /etc/s6/sv
        let mut all_names: Vec<String> = Vec::new();
        if let Ok(mut dir) = tokio::fs::read_dir("/etc/s6/sv").await {
            while let Ok(Some(entry)) = dir.next_entry().await {
                if let Ok(name) = entry.file_name().into_string() {
                    all_names.push(name);
                }
            }
        }
        all_names.sort();

        let mut units = Vec::new();
        for name in all_names {
            let is_active = running.contains(&name);
            let enabled =
                tokio::fs::metadata(format!("/etc/s6-rc/bundle/default/contents.d/{}", name))
                    .await
                    .is_ok();

            // Get pid/uptime from s6-svstat if active
            let (main_pid, up_time) = if is_active {
                self.svstat_info(&name).await
            } else {
                (None, None)
            };

            let _ = daemon_running; // available for future D-Bus enrichment

            units.push(S6UnitStatus {
                id: name,
                active_state: if is_active {
                    "active".to_string()
                } else {
                    "inactive".to_string()
                },
                sub_state: if is_active {
                    "running".to_string()
                } else {
                    "dead".to_string()
                },
                enabled,
                main_pid,
                up_time,
            });
        }
        units
    }

    async fn svstat_info(&self, name: &str) -> (Option<u32>, Option<String>) {
        let path = format!("/etc/s6/sv/{}", name);
        let Ok(output) = tokio::process::Command::new("s6-svstat")
            .arg(&path)
            .output()
            .await
        else {
            return (None, None);
        };
        let text = String::from_utf8_lossy(&output.stdout);
        // "up (pid 1234) 3600 seconds"
        let pid = text
            .split("pid ")
            .nth(1)
            .and_then(|s| s.split(')').next())
            .and_then(|p| p.trim().parse::<u32>().ok());
        let uptime = text.split_whitespace().rev().nth(1).map(|s| s.to_string());
        (pid, uptime)
    }
}

impl Default for S6SystemctlPlugin {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl StatePlugin for S6SystemctlPlugin {
    fn name(&self) -> &str {
        "s6_systemctl"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn is_available(&self) -> bool {
        // Available as long as s6 is installed; daemon liveness is a field in state
        std::path::Path::new("/etc/s6/sv").exists()
    }

    fn schema(&self) -> Option<PluginSchema> {
        Some(
            PluginSchema::builder("s6_systemctl")
                .version("1.0.0")
                .description("s6 service manager — daemon status and unit control")
                .field(
                    "daemon_running",
                    FieldSchema {
                        field_type: FieldType::Boolean,
                        required: true,
                        description: "Whether the op-s6-systemctl D-Bus daemon is reachable"
                            .to_string(),
                        default: Some(json!(false)),
                        example: Some(json!(true)),
                        constraints: Vec::new(),
                        read_only: true,
                        read_only_when: None,
                    },
                )
                .field(
                    "bus_name",
                    FieldSchema {
                        field_type: FieldType::String,
                        required: true,
                        description: "D-Bus well-known name the daemon registers".to_string(),
                        default: Some(json!("org.opdbus.v1.S6.Systemctl")),
                        example: None,
                        constraints: Vec::new(),
                        read_only: true,
                        read_only_when: None,
                    },
                )
                .field(
                    "object_path",
                    FieldSchema {
                        field_type: FieldType::String,
                        required: true,
                        description: "D-Bus object path".to_string(),
                        default: Some(json!("/org/opdbus/v1/s6/systemctl")),
                        example: None,
                        constraints: Vec::new(),
                        read_only: true,
                        read_only_when: None,
                    },
                )
                .field(
                    "interface",
                    FieldSchema {
                        field_type: FieldType::String,
                        required: true,
                        description: "D-Bus interface name".to_string(),
                        default: Some(json!("org.opdbus.v1.S6.Systemctl")),
                        example: None,
                        constraints: Vec::new(),
                        read_only: true,
                        read_only_when: None,
                    },
                )
                .field(
                    "units",
                    FieldSchema {
                        field_type: FieldType::Any,
                        required: true,
                        description: "All s6 service units with live status".to_string(),
                        default: Some(json!([])),
                        example: Some(json!([{
                            "id": "op-projection",
                            "active_state": "active",
                            "sub_state": "running",
                            "enabled": true,
                            "main_pid": 1234,
                            "up_time": "3600"
                        }])),
                        constraints: Vec::new(),
                        read_only: false,
                        read_only_when: None,
                    },
                )
                .build(),
        )
    }


    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
        let current_s: S6SystemctlState = simd_json::serde::from_owned_value(current.clone())?;
        let desired_s: S6SystemctlState = simd_json::serde::from_owned_value(desired.clone())?;
        let mut actions = Vec::new();

        // Diff individual units
        let current_map: std::collections::HashMap<_, _> =
            current_s.units.iter().map(|u| (u.id.clone(), u)).collect();

        for desired_unit in &desired_s.units {
            if let Some(current_unit) = current_map.get(&desired_unit.id) {
                if current_unit.active_state != desired_unit.active_state
                    || current_unit.enabled != desired_unit.enabled
                {
                    actions.push(StateAction::Modify {
                        resource: desired_unit.id.clone(),
                        changes: simd_json::serde::to_owned_value(desired_unit)?,
                    });
                }
            }
        }

        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions,
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: format!("{:x}", md5::compute(simd_json::to_string(current)?)),
                desired_hash: format!("{:x}", md5::compute(simd_json::to_string(desired)?)),
            },
        })
    }

    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        let mut changes_applied = Vec::new();
        let mut errors = Vec::new();

        for action in &diff.actions {
            if let StateAction::Modify { resource, changes } = action {
                let unit: S6UnitStatus = simd_json::serde::from_owned_value(changes.clone())?;

                let state_result = match unit.active_state.as_str() {
                    "active" => {
                        tokio::process::Command::new("s6")
                            .args(["process", "start", resource])
                            .status()
                            .await
                    }
                    "inactive" => {
                        tokio::process::Command::new("s6")
                            .args(["process", "stop", resource])
                            .status()
                            .await
                    }
                    _ => {
                        continue;
                    }
                };

                match state_result {
                    Ok(s) if s.success() => {
                        changes_applied.push(format!("{} -> {}", resource, unit.active_state))
                    }
                    Ok(s) => errors.push(format!(
                        "{}: s6 exited {}",
                        resource,
                        s.code().unwrap_or(-1)
                    )),
                    Err(e) => errors.push(format!("{}: {}", resource, e)),
                }
            }
        }

        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied,
            errors,
            checkpoint: None,
        })
    }

    async fn verify_state(&self, desired: &Value) -> Result<bool> {
        let current = self.query_current_state().await?;
        let current_s: S6SystemctlState = simd_json::serde::from_owned_value(current)?;
        let desired_s: S6SystemctlState = simd_json::serde::from_owned_value(desired.clone())?;

        let current_map: std::collections::HashMap<_, _> = current_s
            .units
            .iter()
            .map(|u| (u.id.clone(), u.active_state.clone()))
            .collect();

        Ok(desired_s.units.iter().all(|u| {
            current_map
                .get(&u.id)
                .map(|s| s == &u.active_state)
                .unwrap_or(false)
        }))
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        let state = self.query_current_state().await?;
        Ok(Checkpoint {
            id: format!("s6_systemctl-{}", chrono::Utc::now().timestamp()),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: state,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, checkpoint: &Checkpoint) -> Result<()> {
        let old: S6SystemctlState =
            simd_json::serde::from_owned_value(checkpoint.state_snapshot.clone())?;
        for unit in old.units {
            let cmd = match unit.active_state.as_str() {
                "active" => "start",
                "inactive" => "stop",
                _ => continue,
            };
            let _ = tokio::process::Command::new("s6")
                .args(["process", cmd, &unit.id])
                .status()
                .await;
        }
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: true,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new("s6_systemctl", |_ctx| std::sync::Arc::new(S6SystemctlPlugin::new()))
}

//! MCP state plugin - manages MCP server configurations and tool groups
//! Wires MCP configuration to the state store for auditing and rollback

use anyhow::{Context, Result};
use async_trait::async_trait;
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use op_state_store::{ExecutionJob, ExecutionStatus, PluginSchema, StateStore};
#[cfg(test)]
use op_state_store::{FieldSchema, FieldType};
use serde::{Deserialize, Serialize};
#[cfg(test)]
use simd_json::json;
use simd_json::OwnedValue as Value;
use std::collections::HashMap;
use std::sync::Arc;
use uuid::Uuid;

/// MCP configuration schema - mirrors the state JSON structure
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct McpConfig {
    /// External MCP servers indexed by name
    #[serde(skip_serializing_if = "Option::is_none")]
    pub servers: Option<HashMap<String, McpServerConfig>>,

    /// Tool groups configuration
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_groups: Option<ToolGroupsConfig>,

    /// Compact mode settings
    #[serde(skip_serializing_if = "Option::is_none")]
    pub compact_mode: Option<CompactModeConfig>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct McpServerConfig {
    /// Server command to execute
    pub command: String,

    /// Command arguments
    #[serde(skip_serializing_if = "Option::is_none")]
    pub args: Option<Vec<String>>,

    /// Environment variables
    #[serde(skip_serializing_if = "Option::is_none")]
    pub env: Option<HashMap<String, String>>,

    /// Whether server is enabled
    #[serde(default = "default_true")]
    pub enabled: bool,

    /// Transport type (stdio, sse, http)
    #[serde(default = "default_stdio")]
    pub transport: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ToolGroupsConfig {
    /// Enabled group IDs
    pub enabled: Vec<String>,

    /// Maximum tools limit
    #[serde(default = "default_max_tools")]
    pub max_tools: usize,

    /// Access zone (localhost, trusted_mesh, private_network, public)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub access_zone: Option<String>,

    /// Trusted network prefixes
    #[serde(skip_serializing_if = "Option::is_none")]
    pub trusted_networks: Option<Vec<String>>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct CompactModeConfig {
    /// Whether compact mode is enabled
    #[serde(default = "default_true")]
    pub enabled: bool,

    /// Meta-tools to expose
    #[serde(default = "default_meta_tools")]
    pub meta_tools: Vec<String>,
}

fn default_true() -> bool {
    true
}

fn default_stdio() -> String {
    "stdio".to_string()
}

fn default_max_tools() -> usize {
    40
}

fn default_meta_tools() -> Vec<String> {
    vec![
        "list_tools".to_string(),
        "search_tools".to_string(),
        "get_tool_schema".to_string(),
        "execute_tool".to_string(),
        "respond".to_string(),
    ]
}

/// Tool definition - canonical schema for all tools
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ToolDefinition {
    pub name: String,
    pub description: String,
    pub input_schema: Value,
    #[serde(default = "default_schema_version")]
    pub schema_version: String,
    #[serde(default)]
    pub category: String,
    #[serde(default)]
    pub tags: Vec<String>,
    #[serde(default = "default_namespace")]
    pub namespace: String,
}

fn default_schema_version() -> String {
    "https://json-schema.org/draft/next/schema".to_string()
}

fn default_namespace() -> String {
    "system.v1".to_string()
}

/// Tool execution result
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExecutionResult {
    pub success: bool,
    pub output: Value,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,
    pub duration_ms: u64,
}

/// MCP state plugin
pub struct McpStatePlugin {
    /// State store for execution tracking
    state_store: Arc<dyn StateStore>,
    /// Configuration file path
    config_path: String,
}

impl McpStatePlugin {
    pub fn new(state_store: Arc<dyn StateStore>, config_path: impl Into<String>) -> Self {
        Self {
            state_store,
            config_path: config_path.into(),
        }
    }

    /// Load current MCP configuration from file
    async fn load_config(&self) -> Result<McpConfig> {
        let content = tokio::fs::read_to_string(&self.config_path).await;

        match content {
            Ok(c) => serde_json::from_str(&c).context("Failed to parse MCP config"),
            Err(_) => {
                // Return default config with requested agents auto-loaded
                let mut servers = HashMap::new();

                // simple, flat list of agents to auto-load
                let agents = vec![
                    "rust-pro",
                    "backend-architect",
                    "network-engineer",
                    "context-manager",
                    "memory",
                    "sequential-thinking",
                ];

                for agent in agents {
                    servers.insert(
                        agent.to_string(),
                        McpServerConfig {
                            command: "dbus-agent".to_string(),
                            args: Some(vec![agent.to_string()]),
                            env: None,
                            enabled: true,
                            transport: "stdio".to_string(),
                        },
                    );
                }

                Ok(McpConfig {
                    servers: Some(servers),
                    tool_groups: Some(ToolGroupsConfig {
                        enabled: vec!["default".to_string()],
                        max_tools: default_max_tools(),
                        access_zone: Some("local".to_string()),
                        trusted_networks: None,
                    }),
                    compact_mode: Some(CompactModeConfig {
                        enabled: true,
                        meta_tools: default_meta_tools(),
                    }),
                })
            }
        }
    }

    /// Save MCP configuration to file
    async fn save_config(&self, config: &McpConfig) -> Result<()> {
        let content = simd_json::to_string_pretty(config)?;
        tokio::fs::write(&self.config_path, content)
            .await
            .context("Failed to write MCP config file")
    }

    /// Apply server configuration changes
    async fn apply_server_config(&self, server_name: &str, config: &McpServerConfig) -> Result<()> {
        // Create execution job for state tracking
        let job = ExecutionJob {
            id: Uuid::new_v4(),
            tool_name: format!("mcp:configure_server:{}", server_name),
            arguments: simd_json::serde::to_owned_value(config)?,
            status: ExecutionStatus::Running,
            created_at: chrono::Utc::now(),
            updated_at: chrono::Utc::now(),
            result: None,
        };

        // Save job to state store
        self.state_store.save_job(&job).await?;

        // Load current config
        let mut current = self.load_config().await.unwrap_or_else(|_| McpConfig {
            servers: Some(HashMap::new()),
            tool_groups: None,
            compact_mode: None,
        });

        // Update server config
        let servers = current.servers.get_or_insert_with(HashMap::new);
        servers.insert(server_name.to_string(), config.clone());

        // Save updated config
        self.save_config(&current).await?;

        // Update job status
        let mut job = job;
        job.status = ExecutionStatus::Completed;
        job.updated_at = chrono::Utc::now();
        job.result = Some(op_state_store::ExecutionResult {
            success: true,
            output: Some(simd_json::serde::to_owned_value(
                "Server configured successfully",
            )?),
            error: None,
        });
        self.state_store.update_job(&job).await?;

        log::info!("Configured MCP server: {}", server_name);
        Ok(())
    }

    /// Apply tool groups configuration
    async fn apply_tool_groups_config(&self, config: &ToolGroupsConfig) -> Result<()> {
        // Create execution job
        let job = ExecutionJob {
            id: Uuid::new_v4(),
            tool_name: "mcp:configure_tool_groups".to_string(),
            arguments: simd_json::serde::to_owned_value(config)?,
            status: ExecutionStatus::Running,
            created_at: chrono::Utc::now(),
            updated_at: chrono::Utc::now(),
            result: None,
        };

        self.state_store.save_job(&job).await?;

        // Load current config
        let mut current = self.load_config().await.unwrap_or_else(|_| McpConfig {
            servers: None,
            tool_groups: Some(config.clone()),
            compact_mode: None,
        });

        // Update tool groups
        current.tool_groups = Some(config.clone());

        // Save updated config
        self.save_config(&current).await?;

        // Update job status
        let mut job = job;
        job.status = ExecutionStatus::Completed;
        job.updated_at = chrono::Utc::now();
        job.result = Some(op_state_store::ExecutionResult {
            success: true,
            output: Some(simd_json::serde::to_owned_value(
                "Tool groups configured successfully",
            )?),
            error: None,
        });
        self.state_store.update_job(&job).await?;

        log::info!("Configured tool groups: {:?}", config.enabled);
        Ok(())
    }
}

